// C program for the function called isbad_alphabet
// Contains target function implementation and dependency signatures

#include <string.h>  /// for strchr and strlen
#include <stdint.h>  /// for CPU arch's optimized int types
#include <stdbool.h> /// for boolean types
#include <stdlib.h>  /// for malloc and free

// Target function implementation
bool isbad_alphabet(const char* alphabet) {
	if (alphabet == NULL) {
		return true;
	}
	uint64_t len = strlen(alphabet);

	/* Checking the length */
	if (len < 2) {
		return true;
	}
	/* Browse the alphabet */
	for (uint64_t i = 0; i < len ; i++) {
		/* Searching for duplicates */
		if (strchr(alphabet + i + 1, alphabet[i]))
			return true;
	}
	return false;
}

